import { request, requestOrNull, seg, Page, requestFile, ExportRequest } from './apiSupport';
import { ActivityDTO } from './ActivityDTO';
import { ActivityKeyDTO } from './ActivityKeyDTO';
import { ActivitySrchDTO } from './ActivitySrchDTO';

/**
 * REST client for Activity.
 *
 * Calls the endpoints ActivityController exposes. Generated from the same model the
 * server is, so a change to the DSL shows up here as a type error rather than
 * at runtime.
 *
 * Generated by ElastiCORE. Do not edit outside the ElastiCORE guidelines.
 */
const BASE = '/api/crm/activity';

/** Registers a new Activity. */
export async function create(input: ActivityDTO, init?: RequestInit): Promise<ActivityDTO> {
    return request<ActivityDTO>('POST', BASE, input, init);
}

/** The Activity with this identifier, or null when there is none. */
export async function findById(activityId: number, init?: RequestInit): Promise<ActivityDTO | null> {
    return requestOrNull<ActivityDTO>('GET', BASE + '/' + seg(activityId), init);
}

/** Every Activity matching the condition. */
export async function search(condition: ActivitySrchDTO, init?: RequestInit): Promise<Page<ActivityDTO>> {
    return request<Page<ActivityDTO>>('POST', BASE + '/search', condition, init);
}

/** Updates an existing Activity. */
export async function update(input: ActivityDTO, init?: RequestInit): Promise<ActivityDTO> {
    return request<ActivityDTO>('PUT', BASE, input, init);
}

/** Updates several in one transaction; none are applied if any fails. */
export async function batchUpdate(inputs: ActivityDTO[], init?: RequestInit): Promise<void> {
    return request<void>('PUT', BASE + '/batch', inputs, init);
}

/** Deletes each key, answering for each whether it was there. */
export async function deleteMany(keys: ActivityKeyDTO[], init?: RequestInit): Promise<boolean[]> {
    return request<boolean[]>('POST', BASE + '/delete', keys, init);
}

/** Deletes the Activity with this identifier. */
export async function deleteById(activityId: number, init?: RequestInit): Promise<boolean> {
    return request<boolean>('DELETE', BASE + '/' + seg(activityId), undefined, init);
}

/** The rows the search finds as a file: CSV, or an .xlsx workbook (format: 'xlsx'). */
export async function exportActivity(body: ExportRequest<ActivitySrchDTO>, init?: RequestInit): Promise<Blob> {
    return requestFile('POST', BASE + '/export', body, init);
}

